import { useRef, useCallback } from "react";

// ── Half-page (top/bottom) split layout ───────────────────────────────────
// Shows the BOTTOM portion of the current page and the TOP portion of the
// next page, stacked vertically, with a draggable divider between them.
//
// Both pages are rendered at full height exactly like in single-page mode —
// this component only controls CLIPPING via two fixed-height `overflow:
// hidden` wrappers. The top pane's inner content is anchored to its own
// bottom edge (`bottom:0`) so the page's top portion is clipped away,
// leaving its bottom slice visible; the bottom pane's content is anchored
// to its own top edge (`top:0`) so the next page's bottom is clipped away.
// No coordinate translation is needed for drawing/pointer handling because
// the canvases themselves are never resized or redrawn — only an ancestor's
// clip box changes, and browsers don't dispatch pointer events into a
// clipped-away area, so touches naturally land on the right page already.
export default function HalfPageView({ frac, onFracChange, topPane, bottomPane }) {
  const containerRef = useRef(null);
  const dragRef       = useRef(false);

  const clampFrac = (f) => Math.min(0.85, Math.max(0.15, f));

  const updateFromClientY = useCallback((clientY) => {
    const el = containerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const f = (clientY - rect.top) / rect.height;
    onFracChange(clampFrac(f));
  }, [onFracChange]);

  const onDividerDown = (e) => {
    e.preventDefault();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    dragRef.current = true;
  };
  const onDividerMove = (e) => {
    if (!dragRef.current) return;
    e.preventDefault();
    updateFromClientY(e.clientY);
  };
  const onDividerUp = () => { dragRef.current = false; };

  const topPct    = Math.round(frac * 1000) / 10;
  const bottomPct = 100 - topPct;

  return (
    <div ref={containerRef} style={{ position: "relative", display: "flex", flexDirection: "column", width: "100%", height: "100%" }}>
      <div style={{ height: `${topPct}%`, overflow: "hidden", position: "relative", flexShrink: 0 }}>
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, display: "flex", justifyContent: "center" }}>
          {topPane}
        </div>
      </div>

      {/* ── Draggable divider ── */}
      <div
        onPointerDown={onDividerDown}
        onPointerMove={onDividerMove}
        onPointerUp={onDividerUp}
        onPointerCancel={onDividerUp}
        style={{
          height: 14, flexShrink: 0, cursor: "row-resize", touchAction: "none",
          display: "flex", alignItems: "center", justifyContent: "center",
          background: "rgba(74,124,89,0.25)", zIndex: 5,
        }}
      >
        <div style={{ width: 44, height: 4, borderRadius: 2, background: "#4a7c59" }} />
      </div>

      <div style={{ height: `${bottomPct}%`, overflow: "hidden", position: "relative", flexShrink: 0 }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 0, display: "flex", justifyContent: "center" }}>
          {bottomPane}
        </div>
      </div>
    </div>
  );
}
