import { useState, useEffect, useCallback, useRef } from "react";
import { getPdfjs } from "../engine/pdfjsSetup";
import { reorderPages, deletePages, splitPage, extractPages } from "./pdfEdit";

const S = {
  es: {
    title: "Organizar páginas", save: "Guardar cambios", cancel: "Cancelar",
    delete: "Eliminar", split: "Dividir", up: "↑", down: "↓",
    vertical: "Vertical (izq/der)", horizontal: "Horizontal (arriba/abajo)",
    selectHint: "Marca páginas para exportarlas",
    exportSel: "Exportar seleccionadas", share: "Compartir", download: "Descargar",
    working: "Procesando…", confirmDelete: "¿Eliminar esta página?",
  },
  en: {
    title: "Organize pages", save: "Save changes", cancel: "Cancel",
    delete: "Delete", split: "Split", up: "↑", down: "↓",
    vertical: "Vertical (left/right)", horizontal: "Horizontal (top/bottom)",
    selectHint: "Check pages to export them",
    exportSel: "Export selected", share: "Share", download: "Download",
    working: "Working…", confirmDelete: "Delete this page?",
  },
};

const btn = { background: "rgba(74,124,89,0.7)", color: "#fff", border: "none", borderRadius: 7, padding: "7px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700 };
const btnGhost = { background: "transparent", color: "#8fbc8f", border: "1px solid rgba(74,124,89,0.5)", borderRadius: 7, padding: "6px 10px", cursor: "pointer", fontSize: 11 };
const btnDanger = { background: "transparent", color: "#fca5a5", border: "1px solid rgba(239,68,68,0.4)", borderRadius: 7, padding: "6px 10px", cursor: "pointer", fontSize: 11 };
const iconBtn = { background: "rgba(255,255,255,0.08)", border: "none", borderRadius: 6, color: "#e8e4d8", cursor: "pointer", width: 26, height: 26, fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center" };

async function renderThumbs(bytes) {
  const doc = await getPdfjs().getDocument({ data: new Uint8Array(bytes.slice(0)) }).promise;
  const out = [];
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    const vp   = page.getViewport({ scale: 1 });
    const scale = 150 / vp.width;
    const svp  = page.getViewport({ scale });
    const cvs  = document.createElement("canvas");
    cvs.width = svp.width; cvs.height = svp.height;
    await page.render({ canvasContext: cvs.getContext("2d"), viewport: svp }).promise;
    out.push(cvs.toDataURL());
    page.cleanup();
  }
  doc.destroy();
  return out;
}

function downloadAndMaybeShare(bytes, filename) {
  const blob = new Blob([bytes], { type: "application/pdf" });
  const url  = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
  if (navigator.canShare) {
    const file = new File([blob], filename, { type: "application/pdf" });
    if (navigator.canShare({ files: [file] })) {
      navigator.share({ files: [file], title: filename }).catch(() => {});
    }
  }
}

export default function OrganizeView({ lang = "es", bytes, fileBaseName = "partitura", onSave, onClose }) {
  const L = S[lang] || S.es;
  const [workingBytes, setWorkingBytes] = useState(bytes);
  const [thumbs, setThumbs]             = useState([]);
  const [busy, setBusy]                 = useState(true);
  const [selected, setSelected]         = useState(() => new Set());
  const [splitFor, setSplitFor]         = useState(null); // page index while axis chooser is open
  const dirtyRef = useRef(false);

  const refreshThumbs = useCallback((b) => {
    setBusy(true);
    renderThumbs(b).then(t => { setThumbs(t); setBusy(false); }).catch(() => setBusy(false));
  }, []);

  useEffect(() => { refreshThumbs(workingBytes); }, [workingBytes, refreshThumbs]);

  const applyEdit = async (fn) => {
    setBusy(true);
    try {
      const next = await fn(workingBytes);
      dirtyRef.current = true;
      setSelected(new Set());
      setWorkingBytes(next);
    } finally {
      setBusy(false);
    }
  };

  const moveUp   = (i) => { if (i === 0) return; const order = thumbs.map((_, idx) => idx); [order[i - 1], order[i]] = [order[i], order[i - 1]]; applyEdit(b => reorderPages(b, order)); };
  const moveDown = (i) => { if (i === thumbs.length - 1) return; const order = thumbs.map((_, idx) => idx); [order[i + 1], order[i]] = [order[i], order[i + 1]]; applyEdit(b => reorderPages(b, order)); };
  const remove   = (i) => { if (!window.confirm(L.confirmDelete)) return; applyEdit(b => deletePages(b, [i], thumbs.length)); };
  const doSplit  = (i, axis) => { setSplitFor(null); applyEdit(b => splitPage(b, i, axis)); };

  const toggleSelect = (i) => setSelected(s => {
    const next = new Set(s);
    next.has(i) ? next.delete(i) : next.add(i);
    return next;
  });

  const exportSelected = async () => {
    if (!selected.size) return;
    const indices = [...selected].sort((a, b) => a - b);
    const out = await extractPages(workingBytes, indices);
    downloadAndMaybeShare(out, `${fileBaseName}-paginas.pdf`);
  };

  const handleSave = () => { onSave(workingBytes); };

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 50, background: "rgba(8,16,10,0.97)", backdropFilter: "blur(10px)", display: "flex", flexDirection: "column", color: "#e8e4d8" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 14px", borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
        <div style={{ fontWeight: 700, fontSize: 14, flex: 1 }}>{L.title}</div>
        {selected.size > 0 && <button style={btnGhost} onClick={exportSelected}>{L.exportSel} ({selected.size})</button>}
        <button style={btnGhost} onClick={onClose}>{L.cancel}</button>
        <button style={btn} onClick={handleSave}>{L.save}</button>
      </div>

      <div style={{ color: "#6b8f6b", fontSize: 11, padding: "6px 14px" }}>{L.selectHint}</div>

      <div style={{ flex: 1, overflowY: "auto", padding: 14, display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 14, opacity: busy ? 0.5 : 1 }}>
        {thumbs.map((src, i) => (
          <div key={i} style={{ background: "rgba(255,255,255,0.05)", borderRadius: 10, padding: 8, position: "relative" }}>
            <label style={{ position: "absolute", top: 6, left: 6, zIndex: 2 }}>
              <input type="checkbox" checked={selected.has(i)} onChange={() => toggleSelect(i)} style={{ accentColor: "#4a7c59", width: 16, height: 16 }} />
            </label>
            <img src={src} alt="" style={{ width: "100%", display: "block", borderRadius: 4, boxShadow: "0 2px 8px rgba(0,0,0,0.4)" }} />
            <div style={{ textAlign: "center", color: "#8fbc8f", fontSize: 11, marginTop: 6 }}>{i + 1}</div>
            <div style={{ display: "flex", gap: 4, marginTop: 6, justifyContent: "center", flexWrap: "wrap" }}>
              <button style={iconBtn} title={L.up} onClick={() => moveUp(i)} disabled={i === 0}>{L.up}</button>
              <button style={iconBtn} title={L.down} onClick={() => moveDown(i)} disabled={i === thumbs.length - 1}>{L.down}</button>
              <button style={btnGhost} onClick={() => setSplitFor(i)}>{L.split}</button>
              <button style={btnDanger} onClick={() => remove(i)}>{L.delete}</button>
            </div>

            {splitFor === i && (
              <div style={{ position: "absolute", inset: 0, background: "rgba(8,16,10,0.95)", borderRadius: 10, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8, padding: 10, zIndex: 3 }}>
                <button style={btn} onClick={() => doSplit(i, "vertical")}>{L.vertical}</button>
                <button style={btn} onClick={() => doSplit(i, "horizontal")}>{L.horizontal}</button>
                <button style={btnGhost} onClick={() => setSplitFor(null)}>{L.cancel}</button>
              </div>
            )}
          </div>
        ))}
      </div>

      {busy && (
        <div style={{ position: "absolute", bottom: 16, left: "50%", transform: "translateX(-50%)", background: "rgba(74,124,89,0.85)", padding: "6px 14px", borderRadius: 20, fontSize: 12, fontWeight: 700 }}>
          {L.working}
        </div>
      )}
    </div>
  );
}
